function sortAZ(x) {
	return Array.from(x).sort((a, b) => {
		const nameA = a.name.toUpperCase(), nameB = b.name.toUpperCase();
		if (nameA < nameB) return -1;
		if (nameA > nameB) return 1;
		return 0;
	});
}
function sortInReverse(x) {
	return Array.from(x).reverse();
}
function sortWeightAsc(x) {
	return Array.from(x).sort((a, b) => {
		return a.weight - b.weight;
	});
}
function sortRatingAsc(x) {
	return Array.from(x).sort((a, b) => {
		return a.rating - b.rating;
	});
}
function sortDamageAsc(x) {
	return Array.from(x).sort((a, b) => {
		return a.damage - b.damage;
	});
}


